You are implementing a Blazor Web App for a logistics company that tracks shipments. The project has already been scaffolded at `/tmp/sv-6dfe8905861341deb3a34ffc67dd379c/ShipmentTracker/` using `dotnet new blazor -int Auto -ai -au Individual`.

The project structure:
- `ShipmentTracker/` - server project
- `ShipmentTracker.Client/` - client (WebAssembly) project  
- Solution file: `ShipmentTracker.sln`

This is Interactive Auto, Global mode. All interactive components MUST go in the `.Client` project. Components cannot access DbContext directly — they must use HTTP APIs via an interface.

## Requirements
1. Dispatchers view a list of shipments with status and destination
2. Customers check their shipment status and estimated delivery
3. Authentication with individual accounts (already scaffolded)
4. Role-based access: "Dispatcher" role for staff, customers just need to be authenticated

## Implementation Tasks

### 1. Remove template pages
Delete these files from `ShipmentTracker.Client/Pages/`:
- `Counter.razor`
- `Weather.razor`

### 2. Create shared models in `ShipmentTracker.Client/Models/Shipment.cs`
```csharp
namespace ShipmentTracker.Client.Models;

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime ShippedDate { get; set; }
    public DateTime EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}
```

### 3. Create service interface in `ShipmentTracker.Client/Services/IShipmentService.cs`
```csharp
namespace ShipmentTracker.Client.Services;

using ShipmentTracker.Client.Models;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<List<Shipment>> GetShipmentsForCustomerAsync(string email);
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}
```

### 4. Create client-side implementation in `ShipmentTracker.Client/Services/ShipmentHttpService.cs`
```csharp
using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentHttpService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
        => await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];

    public async Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
        => await http.GetFromJsonAsync<List<Shipment>>($"api/shipments/customer/{Uri.EscapeDataString(email)}") ?? [];

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => await http.GetFromJsonAsync<Shipment?>($"api/shipments/track/{Uri.EscapeDataString(trackingNumber)}");

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{id}/status", status);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }
}
```

### 5. Create server-side implementation in `ShipmentTracker/Services/ShipmentServerService.cs`
This uses an in-memory list for demo purposes (no extra EF migration needed beyond Identity):
```csharp
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> _shipments = new()
    {
        new() { Id = 1, TrackingNumber = "TRK-001-2026", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, ShippedDate = DateTime.Now.AddDays(-3), EstimatedDelivery = DateTime.Now.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes" },
        new() { Id = 2, TrackingNumber = "TRK-002-2026", Origin = "Chicago, IL", Destination = "Miami, FL", Status = ShipmentStatus.OutForDelivery, ShippedDate = DateTime.Now.AddDays(-5), EstimatedDelivery = DateTime.Now, CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet" },
        new() { Id = 3, TrackingNumber = "TRK-003-2026", Origin = "Seattle, WA", Destination = "Denver, CO", Status = ShipmentStatus.Pending, ShippedDate = DateTime.Now, EstimatedDelivery = DateTime.Now.AddDays(4), CustomerEmail = "alice@example.com", Description = "Medical supplies - 5 boxes" },
        new() { Id = 4, TrackingNumber = "TRK-004-2026", Origin = "Boston, MA", Destination = "Houston, TX", Status = ShipmentStatus.Delivered, ShippedDate = DateTime.Now.AddDays(-7), EstimatedDelivery = DateTime.Now.AddDays(-1), CustomerEmail = "carol@example.com", Description = "Auto parts - 3 crates" },
        new() { Id = 5, TrackingNumber = "TRK-005-2026", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = ShipmentStatus.Delayed, ShippedDate = DateTime.Now.AddDays(-4), EstimatedDelivery = DateTime.Now.AddDays(3), CustomerEmail = "bob@example.com", Description = "Perishable goods - refrigerated" },
    };

    private static int _nextId = 6;

    public Task<List<Shipment>> GetAllShipmentsAsync()
        => Task.FromResult(_shipments.ToList());

    public Task<List<Shipment>> GetShipmentsForCustomerAsync(string email)
        => Task.FromResult(_shipments.Where(s => s.CustomerEmail.Equals(email, StringComparison.OrdinalIgnoreCase)).ToList());

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
        => Task.FromResult(_shipments.FirstOrDefault(s => s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase)));

    public Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var shipment = _shipments.FirstOrDefault(s => s.Id == id)
            ?? throw new InvalidOperationException($"Shipment {id} not found");
        shipment.Status = status;
        return Task.FromResult(shipment);
