### 9. Create Dispatcher page in `ShipmentTracker.Client/Pages/Dispatcher.razor`
```razor
@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Policy = "DispatcherPolicy")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Shipment Dashboard</h1>

@if (_shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Filter by destination..." @bind="_filterText" @bind:event="oninput" />
    </div>

    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Customer</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td>@shipment.TrackingNumber</td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.CustomerEmail</td>
                    <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    <td>
                        <select class="form-select form-select-sm" value="@shipment.Status" @onchange="e => UpdateStatus(shipment, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>

    <p class="text-muted">Showing @FilteredShipments.Count() of @_shipments.Count shipments</p>
}

@code {
    private List<Shipment>? _shipments;
    private string _filterText = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        _shipments?.Where(s => string.IsNullOrEmpty(_filterText)
            || s.Destination.Contains(_filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        _shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = updated.Status;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}
```

### 10. Create Customer tracking page in `ShipmentTracker.Client/Pages/Track.razor`
```razor
@page "/track"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Track Shipments</PageTitle>

<h1>Track Your Shipments</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number..." @bind="_trackingNumber" @bind:event="oninput" />
            <button class="btn btn-primary" @onclick="SearchByTracking" disabled="@string.IsNullOrWhiteSpace(_trackingNumber)">
                Search
            </button>
        </div>
    </div>
</div>

@if (_searchResult is not null)
{
    <div class="card mb-4">
        <div class="card-header">
            <strong>@_searchResult.TrackingNumber</strong> — @_searchResult.Description
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-4">
                    <p><strong>From:</strong> @_searchResult.Origin</p>
                    <p><strong>To:</strong> @_searchResult.Destination</p>
                </div>
                <div class="col-md-4">
                    <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(_searchResult.Status)">@_searchResult.Status</span></p>
                    <p><strong>Shipped:</strong> @_searchResult.ShippedDate.ToString("MMM dd, yyyy")</p>
                </div>
                <div class="col-md-4">
                    <p><strong>Estimated Delivery:</strong></p>
                    <h4>@_searchResult.EstimatedDelivery.ToString("MMM dd, yyyy")</h4>
                </div>
            </div>
        </div>
    </div>
}
else if (_searched)
{
    <div class="alert alert-warning">No shipment found with tracking number "@_trackingNumber".</div>
}

<hr />

<h2>Your Shipments</h2>

@if (_myShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (_myShipments.Count == 0)
{
    <p class="text-muted">No shipments found for your account.</p>
}
else
{
    <div class="row">
        @foreach (var shipment in _myShipments)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@shipment.TrackingNumber</h5>
                        <p class="card-text">@shipment.Description</p>
                        <p><strong>To:</strong> @shipment.Destination</p>
                        <p>
                            <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                        </p>
                        <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<Shipment>? _myShipments;
    private string _trackingNumber = string.Empty;
    private Shipment? _searchResult;
    private bool _searched;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.Identity?.Name ?? string.Empty;
        if (!string.IsNullOrEmpty(email))
        {
            _myShipments = await ShipmentService.GetShipmentsForCustomerAsync(email);
        }
        else
        {
            _myShipments = [];
        }
    }

    private async Task SearchByTracking()
    {
        _searched = true;
        _searchResult = await ShipmentService.GetShipmentByTrackingNumberAsync(_trackingNumber);
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}
```

